struct berval** encode_krb5_key_data(krb5_key_data* key_data_in, int n_key_data, krb5_kvno mkvno) {
    struct berval** encoded_keys = NULL;
    krb5_key_data* key_data = NULL;
    int unique_versions = 0;
    int i, j;

    if (n_key_data <= 0 || key_data_in == NULL) {
        return NULL;
    }

    /* Shallow copy key data */
    key_data = malloc(n_key_data * sizeof(krb5_key_data));
    if (key_data == NULL) {
        return NULL;
    }

    for (i = 0; i < n_key_data; i++) {
        key_data[i] = key_data_in[i];
    }

    /* Count unique key versions */
    for (i = 0; i < n_key_data; i++) {
        int is_unique = 1;
        for (j = 0; j < unique_versions; j++) {
            if (key_data[j].keytype == key_data[i].keytype) {
                is_unique = 0;
                break;
            }
        }

        if (is_unique) {
            key_data[unique_versions] = key_data[i];
            unique_versions++;
        }
    }

    /* Allocate array of berval pointers */
    encoded_keys = calloc(unique_versions, sizeof(struct berval*));
    if (encoded_keys == NULL) {
        free(key_data);
        return NULL;
    }

    for (i = 0; i < unique_versions; i++) {
        krb5_key_data* kd = &key_data[i];
        struct berval* bv = NULL;
        size_t length = kd->length;

        bv = malloc(sizeof(struct berval));
        if (bv == NULL) {
            for (j = 0; j < i; j++) {
                free(encoded_keys[j]);
            }
            free(encoded_keys);
            free(key_data);
            return NULL;
        }

        bv->bv_len = length;
        bv->bv_val = malloc(length);
        if (bv->bv_val == NULL) {
            free(bv);
            for (j = 0; j < i; j++) {
                free(encoded_keys[j]);
            }
            free(encoded_keys);
            free(key_data);
            return NULL;
        }

        memcpy(bv->bv_val, kd->data, length);
        encoded_keys[i] = bv;
    }

    free(key_data);
    return encoded_keys;
}

struct berval** encode_kerberos_key_data(krb5_key_data* key_data_in, int n_key_data, krb5_kvno mkvno) {
    if (n_key_data <= 0 || !key_data_in) {
        return NULL;
    }

    struct berval** encoded_keys = NULL;
    krb5_key_data* key_copy = NULL;
    int unique_versions = 0;
    int i;

    // Count number of unique key versions
    for (i = 0; i < n_key_data; i++) {
        int j;
        int is_duplicate = 0;
        for (j = 0; j < unique_versions; j++) {
            if (key_data_in[i].keytype == encoded_keys[j]->bv_len) {
                is_duplicate = 1;
                break;
            }
        }
        if (!is_duplicate) {
            unique_versions++;
        }
    }

    encoded_keys = calloc(unique_versions, sizeof(struct berval*));
    if (!encoded_keys) {
        return NULL;
    }

    key_copy = calloc(n_key_data, sizeof(krb5_key_data));
    if (!key_copy) {
        free(encoded_keys);
        return NULL;
    }

    for (i = 0; i < n_key_data; i++) {
        key_copy[i] = key_data_in[i];
    }

    int current_index = 0;
    for (i = 0; i < n_key_data; i++) {
        int j;
        int is_duplicate = 0;
        for (j = 0; j < current_index; j++) {
            if (key_copy[i].keytype == encoded_keys[j]->bv_len) {
                is_duplicate = 1;
                break;
            }
        }

        if (!is_duplicate) {
            encoded_keys[current_index] = calloc(1, sizeof(struct berval));
            if (!encoded_keys[current_index]) {
                // Clean up in case of failure
                for (int k = 0; k < current_index; k++) {
                    free(encoded_keys[k]);
                }
                free(encoded_keys);
                free(key_copy);
                return NULL;
            }

            encoded_keys[current_index]->bv_len = key_copy[i].keytype;
            encoded_keys[current_index]->bv_val = malloc(key_copy[i].keyvalue.length + 1);
            if (!encoded_keys[current_index]->bv_val) {
                free(encoded_keys[current_index]);
                for (int k = 0; k < current_index; k++) {
                    free(encoded_keys[k]);
                }
                free(encoded_keys);
                free(key_copy);
                return NULL;
            }

            memcpy(encoded_keys[current_index]->bv_val, key_copy[i].keyvalue.data, key_copy[i].keyvalue.length);
            encoded_keys[current_index]->bv_val[key_copy[i].keyvalue.length] = '\0';
            current_index++;
        }
    }

    free(key_copy);
    return encoded_keys;
}

struct berval** encode_kerberos_key_data(krb5_key_data* key_data_in, int n_key_data, krb5_kvno mkvno) {
    struct berval** encoded_keys = NULL;
    krb5_key_data* key_data_copy = NULL;
    int* unique_kvno = NULL;
    int i, j, k, count = 0;

    if (n_key_data <= 0 || key_data_in == NULL) {
        return NULL;
    }

    key_data_copy = (krb5_key_data*)malloc(n_key_data * sizeof(krb5_key_data));
    if (!key_data_copy) {
        return NULL;
    }

    for (i = 0; i < n_key_data; i++) {
        key_data_copy[i] = key_data_in[i];
    }

    for (i = 0; i < n_key_data; i++) {
        if (key_data_copy[i].key_data_ver == 0) {
            key_data_copy[i].key_data_ver = mkvno;
        }
    }

    unique_kvno = (int*)malloc(n_key_data * sizeof(int));
    if (!unique_kvno) {
        free(key_data_copy);
        return NULL;
    }

    for (i = 0; i < n_key_data; i++) {
        int is_unique = 1;
        for (j = 0; j < count; j++) {
            if (unique_kvno[j] == key_data_copy[i].key_data_ver) {
                is_unique = 0;
                break;
            }
        }

        if (is_unique) {
            unique_kvno[count++] = key_data_copy[i].key_data_ver;
        }
    }

    encoded_keys = (struct berval**)malloc(count * sizeof(struct berval*));
    if (!encoded_keys) {
        free(key_data_copy);
        free(unique_kvno);
        return NULL;
    }

    for (i = 0; i < count; i++) {
        int version = unique_kvno[i];
        int key_count = 0;
        for (j = 0; j < n_key_data; j++) {
            if (key_data_copy[j].key_data_ver == version) {
                key_count++;
            }
        }

        struct berval* bervals = (struct berval*)malloc(key_count * sizeof(struct berval));
        if (!bervals) {
            for (j = 0; j < i; j++) {
                free(encoded_keys[j]);
            }
            free(encoded_keys);
            free(key_data_copy);
            free(unique_kvno);
            return NULL;
        }

        int index = 0;
        for (j = 0; j < n_key_data; j++) {
            if (key_data_copy[j].key_data_ver == version) {
                bervals[index].bv_len = key_data_copy[j].key_data_length;
                bervals[index].bv_val = (char*)malloc(key_data_copy[j].key_data_length);
                if (!bervals[index].bv_val) {
                    for (k = 0; k < index; k++) {
                        free(bervals[k].bv_val);
                    }
                    free(bervals);
                    for (k = 0; k < i; k++) {
                        free(encoded_keys[k]);
                    }
                    free(encoded_keys);
                    free(key_data_copy);
                    free(unique_kvno);
                    return NULL;
                }
                memcpy(bervals[index].bv_val, key_data_copy[j].key_data, key_data_copy[j].key_data_length);
                index++;
            }
        }

        encoded_keys[i] = bervals;
    }

    free(key_data_copy);
    free(unique_kvno);

    return encoded_keys;
}

struct berval** encode_kerberos_key_data(krb5_key_data* key_data_in, int n_key_data, krb5_kvno mkvno) {
    if (n_key_data <= 0 || key_data_in == NULL) {
        return NULL;
    }

    krb5_key_data* key_data = (krb5_key_data*)malloc(n_key_data * sizeof(krb5_key_data));
    if (!key_data) {
        return NULL;
    }

    for (int i = 0; i < n_key_data; i++) {
        key_data[i] = key_data_in[i];
    }

    int unique_versions = 0;
    for (int i = 0; i < n_key_data; i++) {
        if (key_data[i].key_data_ver != 0) {
            unique_versions++;
        }
    }

    struct berval** bervals = (struct berval**)malloc(unique_versions * sizeof(struct berval*));
    if (!bervals) {
        free(key_data);
        return NULL;
    }

    int count = 0;
    for (int i = 0; i < n_key_data; i++) {
        if (key_data[i].key_data_ver == 0) {
            continue;
        }

        struct berval* ber = (struct berval*)malloc(sizeof(struct berval));
        if (!ber) {
            for (int j = 0; j < count; j++) {
                free(bervals[j]);
            }
            free(bervals);
            free(key_data);
            return NULL;
        }

        ber->bv_len = key_data[i].key_data_length;
        ber->bv_val = (char*)malloc(ber->bv_len);
        if (!ber->bv_val) {
            free(ber);
            for (int j = 0; j < count; j++) {
                free(bervals[j]);
            }
            free(bervals);
            free(key_data);
            return NULL;
        }

        memcpy(ber->bv_val, key_data[i].key_data_contents, key_data[i].key_data_length);
        bervals[count++] = ber;
    }

    bervals[count] = NULL;

    free(key_data);
    return bervals;
}

struct berval** encode_krb5_key_data(krb5_key_data* key_data_in, int n_key_data, krb5_kvno mkvno) {
    struct berval** encoded_keys = NULL;
    krb5_key_data* key_data = NULL;
    int i, j, unique_kvno_count = 0;
    int* seen_kvno = NULL;

    if (n_key_data <= 0 || key_data_in == NULL)
        return NULL;

    key_data = malloc(n_key_data * sizeof(krb5_key_data));
    if (key_data == NULL)
        return NULL;

    for (i = 0; i < n_key_data; i++) {
        key_data[i] = key_data_in[i];
        if (key_data[i].keyblock.contents != NULL) {
            key_data[i].keyblock.contents = malloc(key_data[i].keyblock.length);
            if (key_data[i].keyblock.contents == NULL)
                goto cleanup;
            memcpy(key_data[i].keyblock.contents, key_data_in[i].keyblock.contents, key_data[i].keyblock.length);
        }
    }

    seen_kvno = calloc(n_key_data, sizeof(int));
    if (seen_kvno == NULL)
        goto cleanup;

    for (i = 0; i < n_key_data; i++) {
        if (seen_kvno[i])
            continue;
        for (j = i + 1; j < n_key_data; j++) {
            if (key_data[i].keytype == key_data[j].keytype &&
                key_data[i].key_length == key_data[j].key_length &&
                memcmp(key_data[i].keyblock.contents, key_data[j].keyblock.contents, key_data[i].key_length) == 0) {
                seen_kvno[j] = 1;
            }
        }
        unique_kvno_count++;
    }

    encoded_keys = malloc(unique_kvno_count * sizeof(struct berval*));
    if (encoded_keys == NULL)
        goto cleanup;

    unique_kvno_count = 0;

    for (i = 0; i < n_key_data; i++) {
        if (seen_kvno[i])
            continue;

        struct berval* bv = malloc(sizeof(struct berval));
        if (bv == NULL)
            goto cleanup;

        bv->bv_len = key_data[i].key_length;
        bv->bv_val = malloc(bv->bv_len);
        if (bv->bv_val == NULL) {
            free(bv);
            goto cleanup;
        }

        memcpy(bv->bv_val, key_data[i].keyblock.contents, bv->bv_len);

        encoded_keys[unique_kvno_count++] = bv;
    }

    free(seen_kvno);
    free(key_data);
    return encoded_keys;

cleanup:
    if (seen_kvno)
        free(seen_kvno);
    if (key_data) {
        for (i = 0; i < n_key_data; i++) {
            if (key_data[i].keyblock.contents)
                free(key_data[i].keyblock.contents);
        }
        free(key_data);
    }
    if (encoded_keys) {
        for (i = 0; i < unique_kvno_count; i++) {
            if (encoded_keys[i]) {
                if (encoded_keys[i]->bv_val)
                    free(encoded_keys[i]->bv_val);
                free(encoded_keys[i]);
            }
        }
        free(encoded_keys);
    }

    return NULL;
}
